export const DAEMON_OPENAPI_OPERATIONS_BY_ID = Object.fromEntries(
  DAEMON_OPENAPI_OPERATIONS.map((operation) => [operation.operationId, operation]),
) as Record<DaemonApiOperationId, DaemonOpenApiOperation>;

export function buildDaemonApiPath(
  operation: Pick<DaemonOpenApiOperation, "path">,
  pathParams: Record<string, string | number> = {},
): string {
  return operation.path.replace(/:([A-Za-z_][A-Za-z0-9_]*)|[{]([A-Za-z_][A-Za-z0-9_]*)[}]/g, (_, colonKey: string, braceKey: string) => {
    const key = colonKey ?? braceKey;
    const value = pathParams[key];
    if (value === undefined) {
      throw new Error(`missing daemon API path param: ${key}`);
    }
    return encodeURIComponent(String(value));
  });
}

export async function requestDaemonApi<TResponse = unknown, TBody = unknown>(
  config: DaemonApiConfig,
  operationId: DaemonApiOperationId,
  options: DaemonApiRequestOptions<TBody> = {},
): Promise<TResponse> {
  const operation = DAEMON_OPENAPI_OPERATIONS_BY_ID[operationId];
  const baseUrl = config.url.replace(/\/+$/, "");
  const url = new URL(`${baseUrl}${buildDaemonApiPath(operation, options.pathParams)}`);
  for (const [key, value] of Object.entries(options.query ?? {})) {
    if (value !== null && value !== undefined) {
      url.searchParams.set(key, String(value));
    }
  }
  const headers = new Headers(options.headers);
  if (config.token && !headers.has("authorization")) {
    headers.set("authorization", `Bearer ${config.token}`);
  }
  const init: RequestInit = {
    method: operation.method,
    headers,
  };
  if (options.body !== undefined) {
    if (!headers.has("content-type")) {
      headers.set("content-type", "application/json");
    }
    init.body = JSON.stringify(options.body);
  }
  const response = await fetch(url, init);
  if (!response.ok) {
    // The daemon explains its own failures in the body (e.g. a provider key
    // the OS keychain refused, and why). Dropping it left the UI saying only
    // "the local engine returned an error", which is indistinguishable from
    // every other 500 and sent one debugging session chasing the wrong cause.
    let detail = "";
    try {
      const body = await response.text();
      if (body) {
        const parsed = JSON.parse(body);
        detail = String(parsed?.reason ?? parsed?.error ?? "").trim();
      }
    } catch {
      /* a non-JSON or unreadable body just means no detail to add */
    }
    throw new Error(
      detail
        ? `${operation.operationId} failed: ${response.status} — ${detail}`
        : `${operation.operationId} failed: ${response.status}`,
    );
  }
  if (response.status === 204) {
    return undefined as TResponse;
  }
  return (await response.json()) as TResponse;
}
